const questCache = getQuestProgressCache();
let questTextObj: Phaser.GameObjects.Text | null = null;
if (questCache) {
  const estimatedQuests = estimateQuestRewards(questCache, sessionData);
  const estimatedQuestSkor = estimatedQuests.reduce((s, r) => s + r.reward, 0);
  const totalEstimated = estimatedSkor + estimatedQuestSkor;

  statusText.setText(`💰 +${totalEstimated} SKOR 획득!`);
  statusText.setColor('#FFD700');

  if (estimatedQuests.length > 0) {
    const questLabels: Record<string, string> = {
      gold: '금똥', diamond: '다이아', topaz: '토파즈', rainbow: '무지개',
    };
    const questText = estimatedQuests
      .map(r => `${questLabels[r.quest] ?? r.quest} 퀘스트 +${r.reward}`)
      .join(' / ');
    questTextObj = this.add.text(this.scale.width / 2, statusText.y + 23, `🎯 ${questText}`, {
      fontSize: '13px',
      color: '#88ff88',
      stroke: '#000',
      strokeThickness: 2,
      padding: { top: 3 },
    }).setOrigin(0.5).setDepth(200);
  }
